return [{ json: { newIndex } }];

const chatId = $input.first().json.message.chat.id;
const workflowStaticData = $getWorkflowStaticData('global');
const userPlanData = workflowStaticData.userPlans?.[chatId] || {};

const hasLearningPlan = userPlanData.learningPlan && 
                        Array.isArray(userPlanData.learningPlan) && 
                        userPlanData.learningPlan.length > 0;

const currentIndex = userPlanData.currentIndex || 0;
const topicsTarget = userPlanData.topicsTarget || 0;

const isPlanCompleted = hasLearningPlan && currentIndex >= topicsTarget;

let finalHasLearningPlan = hasLearningPlan;
if (isPlanCompleted) {
  if (workflowStaticData.userPlans) {
      delete workflowStaticData.userPlans[chatId];
  }
  finalHasLearningPlan = false;
}

return [{
    json: {
        learningPlanExists: finalHasLearningPlan,
        currentIndex: currentIndex,
        topicsTarget: topicsTarget,
        userMessage: $input.first().json.message.text,
        chatId: chatId
    }
}];

const workflowStaticData = $getWorkflowStaticData('global');

const chatId = $('Telegram Trigger').first().json.message.chat.id;

const userPlanData = workflowStaticData.userPlans?.[chatId] || {};
const learningPlan = userPlanData.learningPlan || [];
const currentIndex = userPlanData.currentIndex || 0;

const topicIndex = Math.floor(currentIndex / 3);  
const subtopicIndex = currentIndex % 3;           

const currentTopic = learningPlan[topicIndex];
const currentSubtopic = currentTopic?.subtopics[subtopicIndex];

const query = currentTopic ? `${currentTopic.topic} ${currentSubtopic}` : "";

return [{
    json: {
        extractedData: query,
        currentTopic: currentTopic?.topic,
        currentSubtopic: currentSubtopic,
        topicIndex: topicIndex,
        subtopicIndex: subtopicIndex,
        currentIndex: currentIndex,
        totalTopics: learningPlan.length,
        chatId: chatId
    }
}];

const response = $input.all()[0].json.output;
const parsed = JSON.parse(response);
return [{
    json: {
        extractedData: parsed.query
    }
}];

const response = $input.first().json.output;
const parsedResponse = JSON.parse(response);
const learningPlan = parsedResponse.structuredPlan || [];

const totalTopics = Array.isArray(learningPlan) ? learningPlan.length : 0;
const topicsTarget = totalTopics * 3;

const chatId = $('Telegram Trigger').first().json.message.chat.id;

const workflowStaticData = $getWorkflowStaticData('global');

if (!workflowStaticData.userPlans) {
    workflowStaticData.userPlans = {};
}

workflowStaticData.userPlans[chatId] = {
    learningPlan: learningPlan,
    currentIndex: 0,
    topicsTarget: topicsTarget
};

return [{
    json: {
        learningPlan: learningPlan,
        planSaved: true,
        messageToUser: parsedResponse.message,
        topicsTarget: topicsTarget,
        chatId: chatId
    }
}];
